<?php
require_once __DIR__ . '/../includes/config.php';
require_role('admin');db_required();$stats=[];foreach(['users'=>'users','events'=>'events','event_requests'=>'event_requests','registrations'=>'registrations'] as $k=>$t){$stats[$k]=$pdo->query("SELECT COUNT(*) FROM {$t}")->fetchColumn();}$up=$pdo->query("SELECT * FROM events WHERE status='approved' AND event_date>=NOW() ORDER BY event_date ASC LIMIT 5")->fetchAll();$requests=$pdo->query("SELECT er.*,u.name FROM event_requests er JOIN users u ON u.id=er.user_id WHERE er.status='pending' ORDER BY er.created_at DESC LIMIT 8")->fetchAll();$vol=$pdo->query("SELECT va.*,u.name,e.title FROM volunteer_applications va JOIN users u ON u.id=va.user_id JOIN events e ON e.id=va.event_id WHERE va.status='pending' ORDER BY va.created_at DESC LIMIT 8")->fetchAll();$coord=$pdo->query("SELECT ca.*,u.name,e.title FROM coordinator_applications ca JOIN users u ON u.id=ca.user_id JOIN events e ON e.id=ca.event_id WHERE ca.status='pending' ORDER BY ca.created_at DESC LIMIT 8")->fetchAll();$page_title='HOD Command Center';require __DIR__.'/../includes/header.php';?><div class="container-fluid dashboard-shell"><div class="row"><aside class="col-lg-2 sidebar p-3"><div class="small text-uppercase text-secondary mb-3 px-2">HOD command</div><a class="active" href="/admin/dashboard.php"><i class="bi bi-grid"></i> Overview</a><a href="/admin/events.php"><i class="bi bi-calendar-event"></i> Events</a><a href="/admin/requests.php"><i class="bi bi-inbox"></i> Event requests</a><a href="/admin/applications.php"><i class="bi bi-people"></i> Team applications</a><a href="/admin/users.php"><i class="bi bi-person-lines-fill"></i> Users</a><a href="/index.php"><i class="bi bi-box-arrow-up-right"></i> Public site</a></aside><main class="col-lg-10 p-4 p-lg-5"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="section-kicker">HOD command center</div><h2 class="fw-bold mb-1">Campus operations</h2><p class="text-secondary mb-0">Review, approve and keep every event moving.</p></div><div class="metric-chip"><span class="status-dot bg-success"></span> System operational</div></div><div class="row g-3 mb-4"><div class="col-sm-6 col-xl-3"><div class="dash-card p-4"><div class="text-secondary small">Total users</div><div class="stat-number mt-2"><?=$stats['users']?></div></div></div><div class="col-sm-6 col-xl-3"><div class="dash-card p-4"><div class="text-secondary small">Events</div><div class="stat-number mt-2"><?=$stats['events']?></div></div></div><div class="col-sm-6 col-xl-3"><div class="dash-card p-4"><div class="text-secondary small">Pending proposals</div><div class="stat-number mt-2"><?=count($requests)?></div></div></div><div class="col-sm-6 col-xl-3"><div class="dash-card p-4"><div class="text-secondary small">Registrations</div><div class="stat-number mt-2"><?=$stats['registrations']?></div></div></div></div><div class="row g-4"><div class="col-xl-7"><div class="dash-card overflow-hidden"><div class="p-4 border-bottom"><div class="section-kicker">Needs attention</div><h5 class="fw-bold mb-0">Event proposals</h5></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Proposal</th><th>Requested by</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><strong><?=e($r['title'])?></strong><div class="small text-secondary"><?=e($r['category'])?></div></td><td><?=e($r['name'])?></td><td><a class="btn btn-sm btn-dark rounded-pill" href="/admin/requests.php?id=<?=$r['id']?>">Review</a></td></tr><?php endforeach;if(!$requests):?><tr><td colspan="3" class="empty">No pending proposals 🎉</td></tr><?php endif;?></tbody></table></div></div></div><div class="col-xl-5"><div class="dash-card p-4"><div class="section-kicker">Next on campus</div><h5 class="fw-bold mb-3">Upcoming events</h5><?php foreach($up as $e):?><div class="d-flex gap-3 align-items-center py-3 border-bottom"><div class="date-pill position-static"><small class="d-block"><?=date('M',strtotime($e['event_date']))?></small><strong><?=date('d',strtotime($e['event_date']))?></strong></div><div><strong><?=e($e['title'])?></strong><div class="small text-secondary"><?=e($e['venue'])?></div></div></div><?php endforeach;if(!$up):?><div class="empty">No approved upcoming events.</div><?php endif;?></div></div><div class="col-12"><div class="dash-card p-4"><div class="d-flex justify-content-between"><div><div class="section-kicker">People</div><h5 class="fw-bold">Pending team applications</h5></div><a href="/admin/applications.php" class="btn btn-light rounded-pill">View all</a></div><div class="row g-3 mt-1"><?php foreach(array_slice(array_merge($vol,$coord),0,6) as $a):?><div class="col-md-6 col-xl-4"><div class="border rounded-4 p-3"><div class="small text-secondary">Application</div><strong><?=e($a['name'])?></strong><div class="small"><?=isset($a['position'])?'Volunteer · '.e($a['position']):'Coordinator'?></div><div class="small text-secondary mt-1"><?=e($a['title'])?></div></div></div><?php endforeach;if(!$vol&&!$coord):?><div class="col-12 empty">No pending applications.</div><?php endif;?></div></div></div></div></main></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
